fn decode_asisdone(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffe0fc00 != 0x5e000400 {
        return Err(DecodeError::Unallocated);
    }
    // 01|op=0|1|111|00|00|imm5=xxxxx|0|imm4=0000|1|Rn=xxxxx|Rd=xxxxx
    if (bits & 0x20007800) == 0 {
        // MOV (scalar)
        // MOV  <V><d>, <Vn>.<T>[<index>]
        // DUP (element)
        // DUP  <V><d>, <Vn>.<T>[<index>]
        let imm5: u8 = ((bits >> 16) & 0x1f) as u8;
        if imm5 & 0xf == 0x0 {
            return Err(DecodeError::UNDEF);
        }
        let size: u8 = (imm5 & 0xf).trailing_zeros() as u8;
        let Rd: u8 = (bits & 0x1f) as u8;
        let Rn: u8 = ((bits >> 5) & 0x1f) as u8;
        let index: u8 = imm5 >> (size + 1);
        Ok(Instruction::MovDupAsisdoneOnly {
            d: match imm5 {
                0x8 | 0x18 => DynScalarSimd::D(DReg::new(Rd)),
                v if v & 0x7 == 0x4 => DynScalarSimd::S(SReg::new(Rd)),
                v if v & 0x3 == 0x2 => DynScalarSimd::H(HReg::new(Rd)),
                v if v & 0x1 == 0x1 => DynScalarSimd::B(BReg::new(Rd)),
                _ => return Err(DecodeError::Unallocated),
            },
            Vn: Rn.into(),
            T: match imm5 {
                0x8 | 0x18 => Arrangement::element(ElementWidth::D),
                v if v & 0x7 == 0x4 => Arrangement::element(ElementWidth::S),
                v if v & 0x3 == 0x2 => Arrangement::element(ElementWidth::H),
                v if v & 0x1 == 0x1 => Arrangement::element(ElementWidth::B),
                _ => return Err(DecodeError::Unallocated),
            },
            index,
        })
    } else {
        Err(DecodeError::Unallocated)
    }
}

